// Copy-paste compute nest. PE=16 SIMD=4 for I=J=K=64 (AutoSA mm).
// Top ABI example: autosa_mm(A[I][K], B[J][K], C[I][J]) — B is J x K.
#define PE 16
#define SIMD 4
data_t Crow[PE][J];
#pragma HLS ARRAY_PARTITION variable=Crow complete dim=1
#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=PE dim=1
#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=SIMD dim=2
#pragma HLS ARRAY_PARTITION variable=local_B cyclic factor=SIMD dim=2
compute_i0: for (int i0 = 0; i0 < I; i0 += PE) {
  init_pe: for (int p = 0; p < PE; ++p) {
#pragma HLS UNROLL
    init_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
      Crow[p][j] = local_C[i0 + p][j];
    }
  }
  compute_k0: for (int k0 = 0; k0 < K; k0 += SIMD) {
    compute_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
      pe_mac: for (int p = 0; p < PE; ++p) {
#pragma HLS UNROLL
        data_t partial = 0;
        simd_k: for (int s = 0; s < SIMD; ++s) {
#pragma HLS UNROLL
          partial += local_A[i0 + p][k0 + s] * local_B[j][k0 + s];
        }
        Crow[p][j] += partial;
      }
    }
  }
  wb_pe: for (int p = 0; p < PE; ++p) {
#pragma HLS UNROLL
    wb_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
      local_C[i0 + p][j] = Crow[p][j];
    }
  }
}
// Success check: pipelined loop is compute_j (not compute_k). DSP ~= PE*SIMD*5 for float (~320 at 16x4).

simd_k: for (int s = 0; s < SIMD; ++s) {
#pragma HLS UNROLL
  partial += local_A[i0 + p][k0 + s] * local_B[j][k0 + s];
}
Crow[p][j] += partial;  // dependence is across k0 (outer), not across pipelined j

// BAD (flash leftover): k is pipelined/carried, one C update, DSP~3
compute_k: for (int k = 0; k < K; ++k) {
  compute_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
    crow[j] += local_A[i][k] * local_B[j][k];  // FP add recurrence across k
  }
}
// GOOD: pipeline independent j; unroll PE; SIMD-k adder tree (see hls-dse-gemm-multi-pe-latency-hiding)

// 512-bit beats (16 floats). Contiguous k is innermost. PIPELINE II=1. Beat unrolled.
// Keep m_axi max_widen_bitwidth=512. B[j0][k] is outside i0. Reuse that B tile across i0.
// Do not add a K loop the seed does not have in order to cut latency.
// Do not raise PE or SIMD to shorten a scalar load.
// Do not stream B once per PE-row group across all of J and K.
// Do not emit AutoSA kernel0 or a C for-loop of mm_pe inside DATAFLOW.
constexpr int BEAT = 16;
load_B: for (int j = 0; j < TJ; ++j) {
  for (int k = 0; k < TK; k += BEAT) {
#pragma HLS PIPELINE II=1
    beat: for (int b = 0; b < BEAT; ++b) {
#pragma HLS UNROLL
      local_B[j][k + b] = B[j0 + j][k + b];
    }
  }
}
// local_B is reused by every i0 in this j0 tile.
// A dataflow region of the three tile stages (load, compute, store) is allowed.
